<?php
require dirname(__DIR__).'/vendor/autoload.php';$app=require dirname(__DIR__).'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\DB;use App\Support\TextEncoding;
$apply=in_array('--apply',$argv,true);$primary=[];$pattern="\u{fffd}|\\\\ufffd|&#65533;|&#x[fF]{3}[dD];";
DB::table('reports as r')->leftJoin('reports_meta as m','m.report_id','=','r.id')->select('r.id','r.slug','r.title','r.keyword','r.key_info','m.id as meta_id','m.content','m.toc')->where(function($q)use($pattern){foreach(['r.title','r.keyword','r.key_info','m.content','m.toc'] as $f)$q->orWhereRaw('CONVERT('.$f.' USING utf8mb4) COLLATE utf8mb4_bin REGEXP ?',[$pattern]);})->orderBy('r.id')->chunk(300,function($rows)use(&$primary){foreach($rows as $r)$primary[$r->slug]=$r;});
echo 'Primary reports requiring original source: '.count($primary).PHP_EOL;flush();
$matches=[];$db=DB::connection('reportdb');$db->table('exceldata')->select('id','url_slug')->orderBy('id')->chunkById(2000,function($rows)use(&$matches,$primary){foreach($rows as $r){$slug=trim($r->url_slug??'','/ ');if(isset($primary[$slug]))$matches[$r->id]=$slug;}});
echo 'Matched original source reports: '.count($matches).PHP_EOL;flush();
$ledger=[];$changed=0;$missing=[];$conflicts=0;
foreach(array_chunk(array_keys($matches),100) as $ids){$sources=$db->table('exceldata')->whereIn('id',$ids)->select('id','Report_Overview','Table_of_Contents')->get();foreach($sources as $source){$r=$primary[$matches[$source->id]];$sourceText=html_entity_decode(strip_tags(TextEncoding::repair(($source->Report_Overview??'').' '.($source->Table_of_Contents??''))),ENT_QUOTES|ENT_HTML5,'UTF-8');$pairs=[];
 $repair=function(string $text,bool $html=false)use($sourceText,&$pairs){
  $text=preg_replace_callback('~[^,\r\n<>]{2,250}~u',function($m)use($sourceText,&$pairs,$html){$raw=$m[0];$fragment=trim($raw);if(!str_contains($fragment,"\u{fffd}")||mb_strlen($fragment)<2)return $raw;$parts=preg_split('/\s+/u',$fragment);$regex='~(?<![\p{L}\p{N}])'.str_replace("\u{fffd}",'.',implode('\s+',array_map(fn($p)=>preg_quote($p,'~'),$parts))).'(?![\p{L}\p{N}])~u';preg_match_all($regex,$sourceText,$found);$valid=array_values(array_unique(array_filter($found[0],fn($v)=>!str_contains($v,"\u{fffd}")&&!str_contains($v,'?'))));if(count($valid)!==1)return $raw;$to=$html?htmlspecialchars($valid[0],ENT_NOQUOTES|ENT_SUBSTITUTE,'UTF-8',false):$valid[0];$pairs[$fragment]=$to;return str_replace($fragment,$to,$raw);},$text);
  return preg_replace_callback("/[\\p{L}\\p{N}\\x{FFFD}'\\x{2019}.\-]+/u",function($m)use($sourceText,&$pairs,$html){$word=$m[0];if(!str_contains($word,"\u{fffd}")||mb_strlen($word)<2||mb_strlen($word)>100)return $word;$regex='~(?<![\p{L}\p{N}])'.str_replace("\u{fffd}",'.',preg_quote($word,'~')).'(?![\p{L}\p{N}])~u';preg_match_all($regex,$sourceText,$matches);$candidates=array_values(array_unique(array_filter($matches[0],fn($s)=>!str_contains($s,"\u{fffd}")&&!str_contains($s,'?'))));if(count($candidates)!==1)return $word;$to=$html?htmlspecialchars($candidates[0],ENT_NOQUOTES|ENT_SUBSTITUTE,'UTF-8',false):$candidates[0];$pairs[$word]=$to;return $to;},$text);
 };
 $updates=[];foreach(['title','keyword','key_info','content','toc'] as $field){$old=$r->$field;if(!is_string($old))continue;$pairs=[];
  if($field==='key_info'){$data=json_decode($old,true);if(!is_array($data))continue;$fixed=$data;foreach($fixed as $k=>$v)if(is_string($v))$fixed[$k]=$repair($v);$new=$fixed===$data?$old:json_encode($fixed,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);}
  else $new=$repair($old,in_array($field,['content','toc'],true));
  if($new===$old)continue;$table=in_array($field,['content','toc'],true)?'reports_meta':'reports';$id=$table==='reports_meta'?$r->meta_id:$r->id;$updates[$table][$field]=[$old,$new];$ledger[$table][$id][$field]=['source_id'=>$source->id,'report_id'=>$r->id,'slug'=>$r->slug,'replacements'=>$pairs];
 }
 if($updates){if($apply)DB::transaction(function()use($updates,$r,&$conflicts){foreach($updates as $table=>$fields){$id=$table==='reports_meta'?$r->meta_id:$r->id;$current=DB::table($table)->where('id',$id)->lockForUpdate()->first(array_keys($fields));$values=[];foreach($fields as $field=>[$old,$new]){if(!$current||$current->$field!==$old){$conflicts++;continue;}$values[$field]=$new;}if($values)DB::table($table)->where('id',$id)->update($values);}});$changed++;}
 }echo 'Original-source recovery progress: '.$changed.' reports updated'.PHP_EOL;flush();}
file_put_contents(storage_path('app/private/encoding-original-source-ledger.json'),json_encode(['changed_reports'=>$changed,'matched_reports'=>count($matches),'conflicts'=>$conflicts,'ledger'=>$ledger],JSON_THROW_ON_ERROR));echo 'SOURCE_RECOVERY_COMPLETE '.json_encode(['changed_reports'=>$changed,'matched_reports'=>count($matches),'conflicts'=>$conflicts]).PHP_EOL;
